// we want to allow starting projects with having nothing but a global cds-dk installed in a watched context.
// In that case, we want to fall back to resolving internal packages from the global cds-dk's own node_modules.
// Enriching NODE_PATH can be used in CJS (require(...)), but not in ESM (import ... from and import(...)),
// which requires a custom loader instead.
// https://nodejs.org/api/esm.html#no-node_path
const { createRequire, registerHooks } = require('node:module')
const { pathToFileURL } = require('node:url')

const ourModules = new Set(['@sap/cds'])

const requireFromHere = createRequire(__filename)
const resolveFromHere = url => pathToFileURL(requireFromHere.resolve(url)).href

registerHooks({
    resolve(specifier, context, nextResolve) {
        try {
            // use default Node resolver first.
            // Note: registering more hooks is UB!
            return nextResolve(specifier, context)
        } catch (error) {
            if (error.code === 'ERR_MODULE_NOT_FOUND' && ourModules.has(specifier)) {
                return { url: resolveFromHere(specifier), shortCircuit: true }
            }
            throw error
        }
    }
})
